'use client'

import type { ColumnDef } from '@tanstack/react-table'
import { ChevronRight } from 'lucide-react'

import { Badge } from '#/components/ui/badge'
import { cn } from '#/lib/utils.ts'
import type { V9Features } from './features'
import type { OrderStatus, ShipmentStatus, TreeRow } from './data'

export const statusStyle: Record<OrderStatus | ShipmentStatus, string> = {
  Processing: 'bg-amber-500/10 text-amber-700 dark:text-amber-400',
  Shipped: 'bg-sky-500/10 text-sky-700 dark:text-sky-400',
  Delivered: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  'Label created': 'bg-muted text-muted-foreground',
  'In transit': 'bg-sky-500/10 text-sky-700 dark:text-sky-400',
  'Out for delivery': 'bg-violet-500/10 text-violet-700 dark:text-violet-400',
}

export const money = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
})

export const day = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeZone: 'UTC',
})

export const columns: ColumnDef<V9Features, TreeRow>[] = [
  {
    id: 'item',
    header: 'Item',
    cell: ({ row }) => {
      const item = row.original
      return (
        <div
          className="flex items-center gap-1.5"
          style={{ paddingLeft: `${row.depth * 1.5}rem` }}
        >
          {row.getCanExpand() ? (
            <button
              type="button"
              onClick={row.getToggleExpandedHandler()}
              className="flex size-4 shrink-0 items-center justify-center text-muted-foreground"
              aria-label={`${row.getIsExpanded() ? 'Collapse' : 'Expand'} order`}
            >
              <ChevronRight
                className={cn(
                  'size-3.5 transition-transform',
                  row.getIsExpanded() && 'rotate-90',
                )}
              />
            </button>
          ) : (
            <span className="w-4 shrink-0" />
          )}
          {item.kind === 'order' ? (
            <span className="font-medium">Order {item.number}</span>
          ) : (
            <span>
              {item.carrier}{' '}
              <span className="font-mono text-xs text-muted-foreground">
                {item.tracking.slice(0, 10)}…
              </span>
            </span>
          )}
        </div>
      )
    },
  },
  {
    id: 'details',
    header: 'Details',
    cell: ({ row }) => {
      const item = row.original
      return item.kind === 'order' ? (
        <div>
          <div>{item.customer}</div>
          <div className="text-xs text-muted-foreground">{item.email}</div>
        </div>
      ) : (
        <span className="text-muted-foreground">{item.destination}</span>
      )
    },
  },
  {
    id: 'status',
    header: 'Status',
    cell: ({ row }) => (
      <Badge variant="secondary" className={statusStyle[row.original.status]}>
        {row.original.status}
      </Badge>
    ),
  },
  {
    id: 'amount',
    header: () => <div className="text-right">Amount</div>,
    cell: ({ row }) => {
      const item = row.original
      return (
        <div className="text-right tabular-nums">
          {item.kind === 'order' ? (
            money.format(item.total)
          ) : (
            <span className="text-muted-foreground">
              {item.items} {item.items === 1 ? 'item' : 'items'}
            </span>
          )}
        </div>
      )
    },
  },
  {
    id: 'date',
    header: 'Date',
    cell: ({ row }) => {
      const item = row.original
      return (
        <span className="whitespace-nowrap text-muted-foreground">
          {item.kind === 'order'
            ? day.format(new Date(item.placedAt))
            : `ETA ${day.format(new Date(item.eta))}`}
        </span>
      )
    },
  },
  {
    id: 'open',
    header: () => <span className="sr-only">Details</span>,
    cell: ({ row }) =>
      row.original.kind === 'shipment' ? (
        <ChevronRight
          aria-hidden
          className="ml-auto size-4 text-muted-foreground"
        />
      ) : null,
    size: 32,
  },
]

'use client'

import { useState } from 'react'
import { flexRender, useTable } from '@tanstack/react-table'
import type { ColumnDef, ExpandedState, Row } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils.ts'
import { v9Features } from './features'
import type { V9Features } from './features'
import { ShipmentCard } from './shipment-card'
import type { Order, Shipment, TreeRow } from './data'

// The card takes this room from the table; its header repeats these values
const hiddenWhileOpen = { details: false, amount: false, date: false }

interface DetailPanelTableProps {
  columns: ColumnDef<V9Features, TreeRow, any>[]
  data: Order[]
}

export function DetailPanelTable({ columns, data }: DetailPanelTableProps) {
  const [expanded, setExpanded] = useState<ExpandedState>(true)
  // Kept after closing so the card keeps its content while it slides out
  const [panel, setPanel] = useState<{
    shipment: Shipment
    order: Order
    trigger: HTMLElement
    open: boolean
  } | null>(null)

  const table = useTable({
    features: v9Features,
    // v9Features registers pagination, which would cut open groups off at 10 rows
    manualPagination: true,
    data,
    columns,
    getRowId: (row) => row.id,
    getSubRows: (row) => (row.kind === 'order' ? row.children : undefined),
    onExpandedChange: setExpanded,
    state: { expanded, columnVisibility: panel?.open ? hiddenWhileOpen : {} },
  })

  function openShipment(row: Row<V9Features, TreeRow>, trigger: HTMLElement) {
    const shipment = row.original
    const order = row.getParentRow()?.original
    if (shipment.kind !== 'shipment' || order?.kind !== 'order') return
    setPanel({ shipment, order, trigger, open: true })
  }

  function closePanel() {
    if (!panel) return
    setPanel({ ...panel, open: false })
    // The card is inert once closed, so hand focus back to the row that opened it
    panel.trigger.focus()
  }

  return (
    // The card is docked inside this box and pushes the table aside as it opens
    <div
      className="relative flex min-h-[36rem] overflow-hidden rounded-md border"
      onKeyDown={(e) => {
        if (e.key === 'Escape' && panel?.open) closePanel()
      }}
    >
      <div className="min-w-0 flex-1 overflow-x-auto">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    style={{ width: header.column.columnDef.size }}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.map((row) => {
              const isShipment = row.original.kind === 'shipment'
              const isOpen =
                isShipment &&
                panel?.open === true &&
                panel.shipment.id === row.id
              return (
                <TableRow
                  key={row.id}
                  tabIndex={isShipment ? 0 : undefined}
                  data-state={isOpen ? 'selected' : undefined}
                  onClick={
                    isShipment
                      ? (e) => openShipment(row, e.currentTarget)
                      : undefined
                  }
                  onKeyDown={
                    isShipment
                      ? (e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            e.preventDefault()
                            openShipment(row, e.currentTarget)
                          }
                        }
                      : undefined
                  }
                  className={cn(
                    isShipment &&
                      'cursor-pointer bg-muted/30 outline-none focus-visible:bg-muted',
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>

      <ShipmentCard
        open={panel?.open === true}
        onClose={closePanel}
        shipment={panel?.shipment ?? null}
        order={panel?.order ?? null}
      />
    </div>
  )
}

import { columns } from './columns'
import { orders } from './data'
import { DetailPanelTable } from './data-table'

export function DetailPanelTableDemo() {
  return <DetailPanelTable columns={columns} data={orders} />
}
